mapper.select:
select model as `key`, count(*) as calls, 0 as value
from ai_llm_call_trace where occurred_at >= #{start}
group by model order by calls desc, model asc

select operation_key as `key`, count(*) as calls, 0 as value
from ai_llm_call_trace where occurred_at >= #{start}
group by operation_key order by calls desc, operation_key asc

select  from ai_llm_call_trace
where occurred_at >= #{start}
order by occurred_at desc, id desc limit 1

select  from ai_llm_call_trace
where run_id = #{runId}
order by occurred_at asc, id asc
limit #{limit}
